import type { HistEvent } from '../types';

export const eventsExtra: HistEvent[] = [
  // ===== Kuno =====
  { id: 'e-sargon', year: -2334, title: 'Sargon dari Akkad mendirikan kekaisaran', region: 'Asia Barat', lon: 44.4, lat: 33.1, description: "Seorang penguasa dari kota Akkad menaklukkan kota-kota Sumer dan menyatukan Mesopotamia di bawah satu raja. Kisah ini bermula dari tokoh yang menurut tradisi bangkit dari pelayan istana; letak persis Akkad hingga kini belum ditemukan. Tahun ±2334 SM adalah perkiraan awal pemerintahannya.", civilizationId: 'mesopotamia', kind: 'politik' },
  { id: 'e-gilgamesh', year: -2100, title: 'Epos Gilgamesh dituliskan', region: 'Asia Barat', lon: 45.64, lat: 31.32, description: "Syair-syair Sumer tentang Gilgamesh, raja Uruk, mulai ditulis pada lempeng tanah liat sekitar 2100 SM. Berabad-abad kemudian, para juru tulis Babilonia merangkainya menjadi satu epos panjang tentang persahabatan, kehilangan, dan ketakutan manusia pada maut. Karya ini termasuk sastra tertua yang masih terbaca.", civilizationId: 'mesopotamia', kind: 'budaya' },
  { id: 'e-akhenaten', year: -1350, title: 'Akhenaten memindahkan ibu kota ke Amarna', region: 'Afrika', lon: 30.9, lat: 27.65, description: "Firaun Akhenaten meninggalkan Thebes dan membangun kota baru bernama Akhetaten untuk memuja Aten, cakram matahari. Perubahan agama ini berlangsung sekitar satu generasi, lalu para penerusnya mengembalikan pemujaan dewa-dewa lama. Tahun yang dipakai adalah perkiraan.", civilizationId: 'mesir-kuno', kind: 'agama' },
  { id: 'e-punt', year: -1470, title: 'Hatshepsut mengirim ekspedisi ke Punt', region: 'Afrika', lon: 32.61, lat: 25.74, description: "Firaun perempuan Hatshepsut mengirim kapal-kapal ke negeri Punt, kemungkinan di pesisir Laut Merah, untuk mendatangkan dupa, kemenyan, dan emas. Relief perjalanan itu masih terpahat di kuil jenazahnya di Deir el-Bahari. Tahun ±1470 SM adalah perkiraan.", civilizationId: 'mesir-kuno', kind: 'perdagangan' },
  { id: 'e-kadesh', year: -1274, title: 'Pertempuran Kadesh', region: 'Asia Barat', lon: 36.52, lat: 34.57, description: "Pasukan Ramses II dari Mesir dan Muwatalli II dari Het bertemu di tepi Sungai Orontes dalam salah satu pertempuran kereta kuda terbesar yang tercatat. Kedua pihak mengaku menang, dan tidak ada yang berhasil menguasai Suriah sepenuhnya. Pertempuran ini berujung pada perjanjian damai belasan tahun kemudian.", civilizationId: 'het', kind: 'perang' },
  { id: 'e-perjanjian-het-mesir', year: -1259, title: 'Perjanjian damai Het–Mesir', region: 'Asia Barat', lon: 34.61, lat: 40.02, description: "Ramses II dan Hattusili III menandatangani perjanjian yang menjadi salah satu kesepakatan damai tertua yang naskahnya masih ada. Salinan Mesir terpahat di dinding kuil, sedangkan salinan Het ditulis pada lempeng tanah liat di Hattusa. Isinya mencakup pertahanan bersama dan penyerahan buronan.", civilizationId: 'het', kind: 'politik' },
  { id: 'e-zaman-perunggu', year: -1177, title: 'Keruntuhan Zaman Perunggu', region: 'Asia Barat', lon: 35.78, lat: 35.6, description: "Dalam beberapa dekade sekitar 1200 SM, Hattusa, Ugarit, dan banyak kota Mediterania timur hancur atau ditinggalkan. Catatan Mesir menyebut kelompok 'Bangsa Laut' sebagai penyerbu, tetapi para sejarawan menduga penyebabnya berlapis: kekeringan, gempa, gagal panen, dan putusnya jalur dagang. Tahun 1177 SM adalah tahun Ramses III menahan serbuan itu.", kind: 'bencana' },
  { id: 'e-tulang-ramalan', year: -1250, title: 'Tulang ramalan Shang di Anyang', region: 'Asia Timur', lon: 114.3, lat: 36.1, description: "Di ibu kota Shang dekat Anyang, juru ramal mengajukan pertanyaan kepada leluhur dengan menggores tulang dan cangkang kura-kura, lalu memanaskannya hingga retak. Goresan itulah tulisan Tionghoa tertua yang diketahui. Tahun ±1250 SM adalah masa puncak kegiatan ini.", civilizationId: 'shang-zhou', kind: 'budaya' },
  { id: 'e-olmek-kepala', year: -1200, title: 'Kepala raksasa Olmek dipahat', region: 'Amerika', lon: -94.76, lat: 17.73, description: "Di San Lorenzo, pemahat Olmek memindahkan balok basal puluhan ton dari pegunungan lalu memahatnya menjadi kepala besar berhelm. Para peneliti menduga kepala-kepala itu menggambarkan penguasa. Tahun ±1200 SM adalah perkiraan masa awal tradisi ini.", civilizationId: 'olmek', kind: 'budaya' },
  { id: 'e-lapita', year: -1500, title: 'Pelaut Lapita menjelajah Pasifik barat', region: 'Oseania', lon: 150.0, lat: -4.5, description: "Penutur bahasa Austronesia membawa tembikar bercorak cap yang disebut Lapita dari kepulauan Bismarck ke arah timur. Dalam beberapa abad mereka sampai ke Vanuatu, Fiji, hingga Tonga dan Samoa dengan perahu bercadik. Tahun ±1500 SM adalah perkiraan kasar.", civilizationId: 'polinesia', kind: 'budaya' },
  { id: 'e-alfabet-fenisia', year: -1050, title: 'Alfabet Fenisia', region: 'Asia Barat', lon: 35.65, lat: 34.12, description: "Para pedagang kota-kota Fenisia seperti Byblos menyederhanakan tulisan menjadi sekitar dua puluh dua huruf yang hanya melambangkan bunyi konsonan. Orang Yunani kemudian menambahkan huruf vokal, dan dari garis itu lahir alfabet Latin yang kita pakai sekarang. Tahun ±1050 SM adalah perkiraan.", civilizationId: 'fenisia-kartago', kind: 'budaya' },
  { id: 'e-chavin', year: -900, title: 'Pusat ziarah Chavín de Huántar', region: 'Amerika', lon: -77.18, lat: -9.59, description: "Di lereng Andes Peru, kompleks kuil dengan lorong-lorong batu dan ukiran makhluk campuran manusia dan hewan menjadi tempat ziarah banyak komunitas. Gaya seninya menyebar luas di Andes. Tahun ±900 SM menandai masa pembangunan yang berkembang.", civilizationId: 'mesoamerika-andes', kind: 'agama' },
  { id: 'e-taharqa', year: -690, title: 'Taharqa menjadi firaun dari Kush', region: 'Afrika', lon: 31.82, lat: 18.54, description: "Taharqa dari Kush naik takhta sebagai firaun Dinasti ke-25 yang menguasai Lembah Nil dari Napata hingga delta. Ia membangun kuil di Mesir dan Nubia, tetapi pasukan Asyur akhirnya mendesaknya kembali ke selatan. Kisahnya mengingatkan bahwa Mesir pernah diperintah dari Afrika sub-Sahara.", civilizationId: 'kush-aksum', kind: 'politik' },
  { id: 'e-babel-586', year: -586, title: 'Pembuangan ke Babilonia', region: 'Asia Barat', lon: 44.42, lat: 32.54, description: "Nebukadnezar II merebut Yerusalem, menghancurkan Bait Suci, dan membawa sebagian penduduknya ke Babilonia. Di pembuangan, kitab-kitab bangsa Israel disusun dan dibaca, sehingga pengalaman ini membentuk identitas agama mereka. Setelah Koresh menaklukkan Babilonia pada 539 SM, sebagian boleh pulang.", civilizationId: 'israel-kuno', kind: 'politik' },
  { id: 'e-persepolis', year: -518, title: 'Persepolis mulai dibangun', region: 'Asia Barat', lon: 52.89, lat: 29.93, description: "Darius I memulai pembangunan kompleks istana di Persepolis untuk upacara dan penerimaan utusan dari seluruh kekaisaran. Relief tangganya memperlihatkan utusan berbagai bangsa membawa persembahan. Pekerjaan berlanjut hingga masa penerusnya; Aleksander membakar kompleks ini pada 330 SM.", civilizationId: 'persia-akhemeniyah', kind: 'budaya' },
  { id: 'e-marathon', year: -490, title: 'Pertempuran Marathon', region: 'Eropa', lon: 23.96, lat: 38.15, description: "Pasukan Athena dan sekutunya dari Plataea menghadapi pasukan Persia yang mendarat di dataran Marathon. Orang Athena menang dan memaksa kapal-kapal Persia pulang. Kemenangan ini menanamkan percaya diri pada warga kota yang baru mencoba demokrasi.", civilizationId: 'yunani-klasik', kind: 'perang' },
  { id: 'e-peloponnesos', year: -431, title: 'Perang Peloponnesos pecah', region: 'Eropa', lon: 23.73, lat: 37.98, description: "Athena dan Sparta, bersama sekutu masing-masing, berperang hampir tiga puluh tahun memperebutkan kendali atas dunia Yunani. Wabah yang melanda Athena dan ekspedisi gagal ke Sisilia melemahkannya. Sparta menang pada 404 SM, tetapi kemenangan itu tidak membawa perdamaian yang langgeng.", civilizationId: 'yunani-klasik', kind: 'perang' },
  { id: 'e-alexandria-perpustakaan', year: -280, title: 'Perpustakaan Aleksandria berkembang', region: 'Afrika', lon: 29.9, lat: 31.2, description: "Di bawah dinasti Ptolemaios, Aleksandria menjadi pusat ilmu yang mengumpulkan gulungan dari seluruh dunia Mediterania. Euklides, Eratosthenes, dan banyak sarjana lain bekerja di sana. Tahun ±280 SM adalah perkiraan masa awal Perpustakaan dan Museion.", civilizationId: 'yunani-klasik', kind: 'budaya' },
  { id: 'e-tembok-qin', year: -214, title: 'Qin menyambung tembok perbatasan utara', region: 'Asia Timur', lon: 108.0, lat: 40.6, description: "Setelah menyatukan Tiongkok, Qin Shi Huang memerintahkan jenderal Meng Tian menyambungkan tembok-tembok lama di utara untuk menahan Xiongnu. Pekerjaan ini menyeret ratusan ribu pekerja dan tentara. Tembok Besar yang kita lihat sekarang sebagian besar berasal dari masa Ming, bukan Qin.", civilizationId: 'qin-han', kind: 'teknologi' },
  { id: 'e-cannae', year: -216, title: 'Pertempuran Cannae', region: 'Eropa', lon: 16.13, lat: 41.3, description: "Hannibal dari Kartago mengepung pasukan Romawi yang jauh lebih besar dengan taktik penjepitan dari sayap. Puluhan ribu prajurit Roma gugur dalam sehari. Meski begitu Roma menolak menyerah dan akhirnya memenangkan perang.", civilizationId: 'fenisia-kartago', kind: 'perang' },
  { id: 'e-rosetta', year: -196, title: 'Dekret Memphis (Prasasti Rosetta)', region: 'Afrika', lon: 31.25, lat: 29.85, description: "Para pendeta Mesir mengeluarkan dekret untuk Ptolemaios V dan memahatnya dalam tiga aksara: hieroglif, demotik, dan Yunani. Ribuan tahun kemudian, batu ini ditemukan tentara Napoleon dan menjadi kunci Champollion membaca hieroglif pada 1822.", civilizationId: 'mesir-kuno', kind: 'budaya' },
  { id: 'e-carrhae', year: -53, title: 'Pertempuran Carrhae', region: 'Asia Barat', lon: 39.03, lat: 36.86, description: "Pasukan Roma di bawah Crassus dihadang pemanah berkuda Parthia dan pasukan berat bersenjata tombak pimpinan Surena. Crassus tewas dan Roma kehilangan panji-panji legiunnya. Pertempuran ini menandai batas timur kekuatan Roma.", civilizationId: 'parthia-sasaniyah', kind: 'perang' },
  { id: 'e-pompeii', year: 79, title: 'Letusan Vesuvius mengubur Pompeii', region: 'Eropa', lon: 14.49, lat: 40.75, description: "Tanggal tradisionalnya 24 Agustus, tetapi temuan arkeologi mengisyaratkan sekitar Oktober, Gunung Vesuvius meletus dan menimbun Pompeii serta Herculaneum dengan abu dan material vulkanik. Ribuan orang tewas. Karena tertimbun cepat, kota ini awet dan kini memberi gambaran langka tentang kehidupan sehari-hari Roma.", civilizationId: 'roma', kind: 'bencana' },
  { id: 'e-teotihuacan', year: 100, title: 'Teotihuacan menjadi kota besar', region: 'Amerika', lon: -98.84, lat: 19.69, description: "Di Lembah Meksiko, Teotihuacan tumbuh menjadi kota dengan jalan lurus, Piramida Matahari, dan permukiman bagi puluhan ribu orang. Nama aslinya tidak diketahui; 'Teotihuacan' diberikan orang Aztek berabad-abad kemudian. Tahun ±100 M adalah perkiraan masa pembangunan monumen besarnya.", civilizationId: 'mesoamerika-andes', kind: 'budaya' },
  { id: 'e-shapur-valerianus', year: 260, title: 'Shapur I menawan Kaisar Valerianus', region: 'Asia Barat', lon: 38.79, lat: 37.16, description: "Dalam pertempuran dekat Edessa, Shapur I dari Sasaniyah mengalahkan pasukan Roma dan menawan Kaisar Valerianus, satu-satunya kaisar Romawi yang tertangkap hidup oleh musuh. Peristiwa ini dipahat dalam relief batu di Naqsh-e Rustam.", civilizationId: 'parthia-sasaniyah', kind: 'perang' },
  { id: 'e-milano', year: 313, title: 'Edik Milano', region: 'Eropa', lon: 9.19, lat: 45.46, description: "Konstantinus dan Licinius sepakat memberi kebebasan beragama di seluruh Kekaisaran, termasuk bagi umat Kristen yang sebelumnya dianiaya. Para sejarawan masih berdebat apakah ini satu edik resmi atau kesepakatan kebijakan. Isinya mengembalikan harta gereja yang disita.", civilizationId: 'roma', kind: 'agama' },
  { id: 'e-nikea', year: 325, title: 'Konsili Nikea', region: 'Asia Barat', lon: 29.72, lat: 40.43, description: "Kaisar Konstantinus mengundang para uskup ke Nikea untuk menyelesaikan perselisihan tentang hakikat Kristus. Konsili menghasilkan rumusan iman yang kemudian dikembangkan menjadi Kredo Nikea. Ini pertemuan besar pertama gereja di bawah perlindungan kaisar.", civilizationId: 'roma', kind: 'agama' },
  { id: 'e-ezana', year: 330, title: 'Aksum memeluk Kristen', region: 'Afrika', lon: 38.72, lat: 14.13, description: "Raja Ezana dari Aksum meninggalkan pemujaan lama dan memeluk Kristen, menurut tradisi lewat pengaruh Frumentius. Koin Aksum kemudian memakai lambang salib. Tahun ±330 adalah perkiraan, dan Aksum menjadi salah satu kerajaan Kristen tertua.", civilizationId: 'kush-aksum', kind: 'agama' },
  { id: 'e-aryabhata', year: 499, title: 'Aryabhata menulis Aryabhatiya', region: 'Asia Selatan', lon: 85.14, lat: 25.6, description: "Matematikawan Aryabhata menulis karya ringkas tentang aritmetika, aljabar, dan astronomi dalam syair, ketika ia berusia sekitar dua puluh tiga tahun. Ia menyebut bahwa Bumi berputar pada porosnya dan menghitung nilai pi dengan baik. Karyanya berpengaruh pada para ilmuwan Islam dan Eropa.", civilizationId: 'gupta', kind: 'teknologi' },
  { id: 'e-hagia-sophia', year: 537, title: 'Hagia Sophia diresmikan', region: 'Eropa', lon: 28.98, lat: 41.01, description: "Justinianus I meresmikan gereja baru dengan kubah raksasa yang dirancang Anthemius dan Isidoros, selesai dalam waktu sekitar lima tahun. Kubahnya tampak melayang di atas cahaya jendela. Bangunan ini kelak menjadi masjid dan kini kembali berfungsi sebagai masjid.", civilizationId: 'bizantium', kind: 'budaya' },
  // ===== Abad pertengahan =====
  { id: 'e-shima', year: 674, title: 'Ratu Shima memerintah Holing', region: 'Nusantara', lon: 110.7, lat: -6.6, description: "Catatan Dinasti Tang menyebut seorang ratu bernama Xi-mo memerintah kerajaan Holing di Jawa pada 674 dan dikenal tegas menegakkan hukum. Para sejarawan menyamakannya dengan Ratu Shima dari Kalingga, tetapi lokasi pasti kerajaannya di Jawa Tengah masih diperdebatkan.", civilizationId: 'kalingga', kind: 'politik' },
  { id: 'e-karbala', year: 680, title: 'Peristiwa Karbala', region: 'Asia Barat', lon: 44.03, lat: 32.61, description: "Husain bin Ali, cucu Nabi Muhammad, dan rombongan kecilnya dihadang pasukan Umayyah di Karbala dan gugur pada 10 Muharram. Peristiwa ini diperingati umat Syiah sebagai Asyura dan membentuk memori agama kaum Muslim hingga sekarang. Umat Sunni dan Syiah menafsirkan maknanya secara berbeda.", civilizationId: 'khilafah', kind: 'agama' },
  { id: 'e-kota-kapur', year: 686, title: 'Prasasti Kota Kapur', region: 'Nusantara', lon: 105.57, lat: -2.5, description: "Di Pulau Bangka, sebuah prasasti berbahasa Melayu Kuno berisi kutukan bagi siapa pun yang tidak setia kepada Sriwijaya dan menyebut rencana ekspedisi ke 'Bhumi Jawa'. Prasasti ini salah satu bukti tertulis tertua tentang Sriwijaya dan bahasa Melayu.", civilizationId: 'sriwijaya', kind: 'politik' },
  { id: 'e-tours', year: 732, title: 'Pertempuran Tours (Poitiers)', region: 'Eropa', lon: 0.34, lat: 46.58, description: "Charles Martel memimpin pasukan Frank menghadapi pasukan Umayyah dari Andalusia di antara Tours dan Poitiers. Pasukan Umayyah mundur, dan para sejarawan masa kini menilai peristiwa ini lebih sebagai bentrokan perbatasan ketimbang titik balik peradaban.", civilizationId: 'frank-romawi-suci', kind: 'perang' },
  { id: 'e-an-lushan', year: 755, title: 'Pemberontakan An Lushan', region: 'Asia Timur', lon: 116.4, lat: 39.9, description: "Jenderal An Lushan, keturunan campuran Sogdia dan Turki, memberontak melawan Tang dan merebut Luoyang serta Chang'an. Delapan tahun perang dan kelaparan menewaskan banyak orang, dan Tang tidak pernah kembali sekuat sebelumnya.", civilizationId: 'tang-song', kind: 'perang' },
  { id: 'e-lindisfarne', year: 793, title: 'Serangan Viking ke Lindisfarne', region: 'Eropa', lon: -1.8, lat: 55.67, description: "Kapal-kapal dari utara mendarat di biara Lindisfarne di pantai Inggris, menjarah dan membunuh para biarawan. Peristiwa ini umumnya dianggap awal Zaman Viking, ketika pelaut Skandinavia berdagang, menyerbu, dan menetap di Eropa.", civilizationId: 'viking', kind: 'perang' },
  { id: 'e-karel-agung', year: 800, title: 'Karel Agung dimahkotai kaisar', region: 'Eropa', lon: 12.45, lat: 41.9, description: "Pada hari Natal, Paus Leo III memahkotai raja Frank Karel Agung sebagai kaisar di Roma. Wilayahnya mencakup Prancis, Jerman barat, dan Italia utara. Ia dikenang karena mendukung sekolah biara dan penyalinan naskah kuno.", civilizationId: 'frank-romawi-suci', kind: 'politik' },
  { id: 'e-blanjong', year: 914, title: 'Prasasti Blanjong', region: 'Nusantara', lon: 115.26, lat: -8.69, description: "Prasasti pilar batu dari Sanur menyebut Sri Kesari Warmadewa, penguasa Bali, dan merupakan salah satu prasasti Bali tertua yang bertarikh. Tulisannya memakai dua aksara: Bali Kuno dan Sanskerta.", civilizationId: 'bali', kind: 'politik' },
  { id: 'e-cordoba', year: 929, title: 'Abdurrahman III memproklamasikan khilafah Cordoba', region: 'Eropa', lon: -4.78, lat: 37.88, description: "Penguasa Umayyah di Andalusia, Abdurrahman III, menyebut dirinya khalifah dan membangun Cordoba sebagai kota ilmu dengan perpustakaan besar dan banyak penerjemah. Umat Muslim, Kristen, dan Yahudi hidup berdampingan, meski ketegangan sesekali muncul.", civilizationId: 'khilafah', kind: 'politik' },
  { id: 'e-rus-baptis', year: 988, title: 'Vladimir membaptis Kiev', region: 'Eropa', lon: 30.52, lat: 50.45, description: "Pangeran Vladimir dari Kiev memeluk Kristen Ortodoks Bizantium dan memerintahkan rakyat dibaptis di Sungai Dnieper. Keputusan ini mengikat Rus' pada dunia Bizantium dan membawa aksara Kiril serta arsitektur gereja.", civilizationId: 'kievan-rus', kind: 'agama' },
  { id: 'e-vinland', year: 1000, title: 'Pelaut Norse mencapai Vinland', region: 'Amerika', lon: -55.62, lat: 51.59, description: "Saga Islandia menceritakan Leif Erikson berlayar ke barat dan menemukan tanah bernama Vinland. Pada 1960 arkeolog menemukan permukiman Norse di L'Anse aux Meadows, Newfoundland, bukti kontak Eropa dengan Amerika sekitar lima abad sebelum Columbus.", civilizationId: 'viking', kind: 'perdagangan' },
  { id: 'e-genji', year: 1008, title: 'Hikayat Genji ditulis', region: 'Asia Timur', lon: 135.77, lat: 35.01, description: "Murasaki Shikibu, dayang istana Heian, menulis kisah Pangeran Genji dalam puluhan bab. Karya ini sering disebut novel pertama dunia karena menggambarkan perasaan tokohnya secara rinci. Tahun ±1008 adalah perkiraan, berdasarkan buku harian yang menyebutnya.", civilizationId: 'jepang-klasik', kind: 'budaya' },
  { id: 'e-sanghyang-tapak', year: 1030, title: 'Prasasti Sanghyang Tapak', region: 'Nusantara', lon: 106.78, lat: -6.89, description: "Prasasti dari Cibadak, Sukabumi, menyebut Sri Jayabupati dari Sunda yang menetapkan sebuah kawasan sungai sebagai tempat suci yang tak boleh dijarah. Prasasti ini penting karena berasal dari Jawa bagian barat dan ditulis dalam aksara Jawa Kuno.", civilizationId: 'sunda-pajajaran', kind: 'politik' },
  { id: 'e-bagan', year: 1057, title: 'Anawrahta menaklukkan Thaton', region: 'Asia Tenggara', lon: 94.86, lat: 21.17, description: "Raja Anawrahta dari Bagan menaklukkan kerajaan Mon di Thaton dan membawa pulang para biksu, naskah Buddha Theravada, dan pengrajin. Dari sini Bagan berkembang menjadi pusat ribuan candi bata yang masih berdiri di dataran Irrawaddy.", civilizationId: 'bagan-burma', kind: 'politik' },
  { id: 'e-manzikert', year: 1071, title: 'Pertempuran Manzikert', region: 'Asia Barat', lon: 42.54, lat: 39.15, description: "Pasukan Seljuk di bawah Alp Arslan mengalahkan tentara Bizantium dan menawan Kaisar Romanos IV. Setelah itu suku-suku Turki bergerak masuk ke Anatolia, yang secara perlahan mengubah wilayah itu menjadi tanah Turki dan Muslim.", civilizationId: 'bizantium', kind: 'perang' },
  { id: 'e-salib-1', year: 1096, title: 'Perang Salib Pertama', region: 'Asia Barat', lon: 35.23, lat: 31.78, description: "Setelah seruan Paus Urbanus II pada 1095, ribuan kesatria dan peziarah Eropa berangkat ke Timur dan merebut Yerusalem pada 1099 dengan pembantaian besar penduduknya. Para penguasa Muslim yang terpecah belah awalnya sulit menghadang mereka.", kind: 'perang' },
  { id: 'e-hattin', year: 1187, title: 'Pertempuran Hattin', region: 'Asia Barat', lon: 35.45, lat: 32.8, description: "Salahuddin al-Ayyubi mengalahkan pasukan Kerajaan Yerusalem di dekat Danau Tiberias, lalu merebut Yerusalem beberapa bulan kemudian. Ia memperlakukan penduduk kota dengan lebih lunak daripada para penakluk sebelumnya.", civilizationId: 'khilafah', kind: 'perang' },
  { id: 'e-lalibela', year: 1200, title: 'Gereja-gereja batu Lalibela', region: 'Afrika', lon: 39.04, lat: 12.03, description: "Di dataran tinggi Ethiopia, belasan gereja dipahat langsung ke dalam batuan, dari atas ke bawah, tanpa disusun bata. Tradisi mengaitkannya dengan Raja Lalibela, dan hingga kini umat masih beribadah di sana. Tahun ±1200 adalah perkiraan.", civilizationId: 'etiopia', kind: 'agama' },
  { id: 'e-konstantinopel-1204', year: 1204, title: 'Perang Salib Keempat menjarah Konstantinopel', region: 'Eropa', lon: 28.98, lat: 41.01, description: "Pasukan salib yang dibawa Venesia berbelok dari rencana ke Mesir dan menyerbu kota Kristen Konstantinopel, menjarahnya selama berhari-hari. Bizantium terpecah menjadi beberapa negara, dan baru kembali pada 1261.", civilizationId: 'bizantium', kind: 'perang' },
  { id: 'e-tripitaka-koreana', year: 1251, title: 'Tripitaka Koreana rampung', region: 'Asia Timur', lon: 126.49, lat: 37.7, description: "Di tengah invasi Mongol, Goryeo memahat seluruh kitab suci Buddha pada sekitar delapan puluh ribu balok kayu. Balok-balok itu kini tersimpan di Haeinsa dan diakui UNESCO. Pemahatan memakan waktu belasan tahun.", civilizationId: 'korea', kind: 'budaya' },
  { id: 'e-baghdad-1258', year: 1258, title: 'Mongol menaklukkan Baghdad', region: 'Asia Barat', lon: 44.36, lat: 33.31, description: "Pasukan Hulagu mengepung dan merebut Baghdad, mengakhiri kekhalifahan Abbasiyah di sana. Banyak penduduk tewas dan perpustakaan dirusak; angka korban dalam sumber berbeda-beda dan sering dibesar-besarkan.", civilizationId: 'mongol', kind: 'perang' },
  { id: 'e-ain-jalut', year: 1260, title: 'Pertempuran Ain Jalut', region: 'Asia Barat', lon: 35.35, lat: 32.55, description: "Pasukan Mamluk Mesir menahan pasukan Mongol di Palestina, kekalahan besar pertama Mongol di medan perang terbuka. Setelahnya Mongol tidak lagi memperluas wilayah ke Mesir.", civilizationId: 'mongol', kind: 'perang' },
  { id: 'e-yuan', year: 1271, title: 'Kubilai mendirikan Dinasti Yuan', region: 'Asia Timur', lon: 116.4, lat: 39.9, description: "Kubilai Khan memakai nama Yuan bagi pemerintahannya dan membangun ibu kota Dadu (Beijing sekarang). Ia menaklukkan Song Selatan pada 1279 sehingga seluruh Tiongkok berada di bawah penguasa Mongol.", civilizationId: 'mongol', kind: 'politik' },
  { id: 'e-mongol-jepang', year: 1274, title: 'Mongol menyerbu Jepang', region: 'Asia Timur', lon: 130.4, lat: 33.65, description: "Armada Yuan menyerang Teluk Hakata pada 1274 dan 1281. Pasukan samurai dan tembok pantai menahan sebagian serangan, sedangkan topan menghancurkan banyak kapal pada serangan kedua. Jepang menyebutnya kamikaze, angin ilahi.", civilizationId: 'jepang-klasik', kind: 'perang' },
  { id: 'e-bach-dang', year: 1288, title: 'Pertempuran Sungai Bach Dang', region: 'Asia Tenggara', lon: 106.8, lat: 20.9, description: "Jenderal Tran Hung Dao menancapkan pasak di dasar sungai saat air pasang dan menjebak armada Yuan ketika air surut. Kemenangan ini menutup invasi ketiga Mongol ke Dai Viet.", civilizationId: 'dai-viet', kind: 'perang' },
  { id: 'e-kilwa', year: 1331, title: 'Ibnu Battuta mengunjungi Kilwa', region: 'Afrika', lon: 39.52, lat: -8.96, description: "Pengelana Maroko Ibnu Battuta singgah di Kilwa, kota pelabuhan Swahili di pantai Afrika Timur, dan menggambarkannya sebagai kota yang indah dengan sultan dermawan. Dari sini emas dan gading dikirim ke Samudra Hindia.", civilizationId: 'afrika-timur-selatan', kind: 'perdagangan' },
  { id: 'e-ayutthaya', year: 1351, title: 'Ayutthaya didirikan', region: 'Asia Tenggara', lon: 100.56, lat: 14.35, description: "Raja Ramathibodi I (U Thong) mendirikan kota Ayutthaya di pulau di antara tiga sungai. Selama sekitar empat abad ia menjadi ibu kota kerajaan dan pelabuhan dagang yang ramai bagi pedagang Tiongkok, Persia, dan Eropa.", civilizationId: 'ayutthaya-siam', kind: 'politik' },
  { id: 'e-zimbabwe', year: 1350, title: 'Zimbabwe Raya berada di puncaknya', region: 'Afrika', lon: 30.93, lat: -20.27, description: "Di dataran tinggi selatan Afrika, penduduk membangun tembok batu besar tanpa perekat. Kota ini berdagang emas dengan pelabuhan pesisir yang terhubung ke Samudra Hindia. Tahun ±1350 adalah perkiraan masa puncaknya.", civilizationId: 'afrika-timur-selatan', kind: 'perdagangan' },
  { id: 'e-bubat', year: 1357, title: 'Perang Bubat', region: 'Nusantara', lon: 112.4, lat: -7.55, description: "Menurut Kidung Sunda dan Pararaton, rombongan raja Sunda yang membawa putri untuk dinikahkan dengan Hayam Wuruk dihadang pasukan Majapahit di Bubat, dan hampir semuanya gugur. Sejarawan membedakan antara fakta inti dan tambahan sastra di dalam kisahnya.", civilizationId: 'sunda-pajajaran', kind: 'perang' },
  { id: 'e-ankara', year: 1402, title: 'Pertempuran Ankara', region: 'Asia Barat', lon: 32.86, lat: 39.93, description: "Timur mengalahkan Sultan Bayezid I dari Utsmaniyah dan menawannya. Utsmaniyah jatuh ke dalam masa perebutan takhta di antara putra-putranya dan baru pulih sekitar sepuluh tahun kemudian.", civilizationId: 'timuriyah', kind: 'perang' },
  { id: 'e-le-loi', year: 1428, title: 'Le Loi menjadi kaisar Dai Viet', region: 'Asia Tenggara', lon: 105.85, lat: 21.03, description: "Setelah sepuluh tahun perang gerilya melawan pasukan Ming, Le Loi mengusir mereka dan naik takhta, mendirikan Dinasti Le Akhir. Nguyen Trai menulis maklumat kemerdekaan yang menjadi teks klasik Vietnam.", civilizationId: 'dai-viet', kind: 'politik' },
  { id: 'e-pachacuti', year: 1438, title: 'Pachacuti membangun kerajaan Inka', region: 'Amerika', lon: -71.97, lat: -13.52, description: "Setelah mengalahkan suku Chanca yang mengepung Cusco, Pachacuti membangun kembali kota itu dan mulai memperluas wilayah Inka menjadi Tawantinsuyu. Dalam waktu satu generasi, kekuasaannya membentang di sepanjang Andes. Tahun ±1438 adalah perkiraan.", civilizationId: 'mesoamerika-andes', kind: 'politik' },
  { id: 'e-hangul', year: 1446, title: 'Hangul diumumkan', region: 'Asia Timur', lon: 126.98, lat: 37.57, description: "Raja Sejong dan para sarjana istananya menciptakan aksara fonetik Hangul agar rakyat biasa dapat membaca dan menulis tanpa harus menguasai aksara Tionghoa. Aksara ini diumumkan secara resmi pada 1446.", civilizationId: 'korea', kind: 'budaya' },
  { id: 'e-vijaya', year: 1471, title: 'Vijaya, ibu kota Champa, jatuh', region: 'Asia Tenggara', lon: 109.2, lat: 13.9, description: "Pasukan Dai Viet di bawah Le Thanh Tong merebut Vijaya dan menawan raja Champa. Wilayah utara Champa lenyap dari peta, dan sisanya hidup sebagai kerajaan kecil di selatan hingga abad ke-19.", civilizationId: 'champa', kind: 'perang' },
  { id: 'e-moai', year: 1250, title: 'Pemahatan moai di Rapa Nui', region: 'Oseania', lon: -109.29, lat: -27.12, description: "Penduduk Rapa Nui memahat ratusan patung batu besar dari tebing gunung berapi Rano Raraku, lalu memindahkannya ke pantai. Pemahatan berlangsung selama beberapa abad; tahun ±1250 adalah perkiraan kasar masa awalnya.", civilizationId: 'polinesia', kind: 'budaya' },
  { id: 'e-maori', year: 1280, title: 'Penduduk Polinesia tiba di Aotearoa', region: 'Oseania', lon: 175.0, lat: -38.0, description: "Pelaut Polinesia berlayar ribuan kilometer dengan perahu bercadik ganda dan menetap di Aotearoa (Selandia Baru). Keturunan mereka dikenal sebagai Maori. Tahun ±1280 adalah perkiraan dari penanggalan radiokarbon.", civilizationId: 'polinesia', kind: 'budaya' },
  // ===== Awal modern =====
  { id: 'e-chaldiran', year: 1514, title: 'Pertempuran Chaldiran', region: 'Asia Barat', lon: 44.38, lat: 39.08, description: "Pasukan Utsmaniyah di bawah Selim I mengalahkan Ismail I dari Safawi, terutama berkat meriam dan senapan yang tidak dimiliki pasukan berkuda Safawi. Tabriz sempat diduduki, dan perbatasan Utsmaniyah–Iran bertahan sampai berabad-abad kemudian.", civilizationId: 'safawi', kind: 'perang' },
  { id: 'e-banjar-1526', year: 1526, title: 'Kesultanan Banjar berdiri', region: 'Nusantara', lon: 114.59, lat: -3.32, description: "Pangeran Samudera, dengan dukungan Demak, memenangkan perebutan takhta dari pamannya dan memeluk Islam dengan gelar Sultan Suriansyah. Tahun 1526 umumnya dipakai sebagai awal kesultanan di tepi Sungai Barito dan Martapura.", civilizationId: 'banjar', kind: 'politik' },
  { id: 'e-lepanto', year: 1571, title: 'Pertempuran Lepanto', region: 'Eropa', lon: 21.2, lat: 38.3, description: "Armada Liga Suci (Spanyol, Venesia, Paus) mengalahkan armada Utsmaniyah dalam pertempuran kapal dayung terbesar dalam sejarah. Utsmaniyah segera membangun kembali armadanya, sehingga dampaknya bagi kekuasaan di Mediterania terbatas.", kind: 'perang' },
  { id: 'e-pakuan', year: 1579, title: 'Pakuan Pajajaran jatuh', region: 'Nusantara', lon: 106.79, lat: -6.6, description: "Pasukan Banten di bawah Maulana Yusuf merebut Pakuan, ibu kota Pajajaran, dan menandai akhir kerajaan Sunda yang telah berdiri berabad-abad. Para bangsawan dan rakyat tersebar ke pedalaman.", civilizationId: 'sunda-pajajaran', kind: 'perang' },
  { id: 'e-armada-spanyol', year: 1588, title: 'Armada Spanyol kalah', region: 'Eropa', lon: 2.1, lat: 51.0, description: "Armada besar Filipus II berlayar menyerbu Inggris, tetapi kapal-kapal api, badai, dan taktik Inggris mencerai-beraikannya. Kekalahan ini memperkuat posisi Inggris di laut, tanpa langsung menjatuhkan Spanyol.", civilizationId: 'inggris-raya', kind: 'perang' },
  { id: 'e-imjin', year: 1592, title: 'Perang Imjin dan Yi Sun-sin', region: 'Asia Timur', lon: 129.04, lat: 35.1, description: "Toyotomi Hideyoshi menyerbu Korea dengan puluhan ribu pasukan. Laksamana Yi Sun-sin memotong jalur logistik Jepang lewat kemenangan laut dengan kapal kura-kura, dan bersama bantuan Ming perang berakhir pada 1598.", civilizationId: 'korea', kind: 'perang' },
  { id: 'e-isfahan', year: 1598, title: 'Isfahan menjadi ibu kota Safawi', region: 'Asia Barat', lon: 51.68, lat: 32.65, description: "Abbas I memindahkan ibu kota dari Qazvin ke Isfahan dan membangunnya dengan lapangan Naqsh-e Jahan, masjid, serta pasar beratap. Kota ini menjadi pusat perdagangan sutra yang ramai.", civilizationId: 'safawi', kind: 'politik' },
  { id: 'e-sekigahara', year: 1600, title: 'Pertempuran Sekigahara', region: 'Asia Timur', lon: 136.47, lat: 35.37, description: "Pasukan Tokugawa Ieyasu mengalahkan koalisi daimyo pendukung putra Hideyoshi dalam satu hari. Tiga tahun kemudian Ieyasu menjadi shogun dan membuka masa Edo yang berlangsung lebih dari dua abad.", civilizationId: 'jepang-klasik', kind: 'perang' },
  { id: 'e-banda', year: 1621, title: 'VOC menaklukkan Kepulauan Banda', region: 'Nusantara', lon: 129.9, lat: -4.52, description: "J. P. Coen mengirim pasukan ke Banda untuk memegang monopoli pala. Ribuan orang Banda tewas, kelaparan, atau dibawa sebagai budak ke Batavia, dan sebagian melarikan diri ke Kepulauan Kei. Perkebunan pala kemudian dikerjakan budak.", civilizationId: 'hindia-belanda', kind: 'perang' },
  { id: 'e-bima-islam', year: 1621, title: 'Bima menerima Islam', region: 'Nusantara', lon: 118.72, lat: -8.46, description: "Menurut tradisi lokal, Islam resmi diterima di Bima pada awal abad ke-17 dengan dukungan pelaut Makassar. Raja Bima kemudian bergelar sultan, dan penanggalan persisnya (1621 atau 1640) masih dibahas para ahli.", civilizationId: 'bima', kind: 'agama' },
  { id: 'e-bongaya', year: 1667, title: 'Perjanjian Bongaya', region: 'Nusantara', lon: 119.41, lat: -5.14, description: "Setelah perang berbulan-bulan, Sultan Hasanuddin dari Gowa menandatangani perjanjian dengan VOC yang dibantu pasukan Arung Palakka dari Bone. Gowa kehilangan monopoli dan sebagian wilayah, sehingga Bone naik menjadi sekutu utama VOC di Sulawesi Selatan.", civilizationId: 'bone-bugis', kind: 'politik' },
  { id: 'e-marege', year: 1720, title: 'Pelaut Makassar berlayar ke Marege\'', region: 'Oseania', lon: 135.0, lat: -12.3, description: "Nelayan Makassar berlayar tiap tahun ke pantai utara Australia (Marege') untuk mencari teripang dan berdagang dengan penduduk Aborigin seperti orang Yolngu. Para ahli masih berdebat soal awal kegiatan ini; tahun ±1720 adalah perkiraan, dan sebagian menduga lebih awal.", civilizationId: 'aborigin-australia', kind: 'perdagangan' },
  { id: 'e-siak', year: 1722, title: 'Kesultanan Siak berdiri', region: 'Nusantara', lon: 102.0, lat: 0.8, description: "Raja Kecil, yang mengaku keturunan Sultan Johor, mendirikan kerajaan di tepi Sungai Siak di Sumatra. Kesultanan ini menguasai perdagangan hasil hutan dan timah di Selat Malaka.", civilizationId: 'siak', kind: 'politik' },
  { id: 'e-geger-pacinan', year: 1740, title: 'Pembantaian Tionghoa di Batavia', region: 'Nusantara', lon: 106.82, lat: -6.13, description: "Setelah ketegangan akibat pengangguran dan kebijakan VOC, pasukan dan penduduk Batavia membunuh ribuan orang Tionghoa (perkiraan sampai sekitar 10.000). Pelarian Tionghoa kemudian bergabung dengan orang Jawa melawan VOC dalam Geger Pacinan.", civilizationId: 'hindia-belanda', kind: 'perang' },
  { id: 'e-ayutthaya-1767', year: 1767, title: 'Ayutthaya dihancurkan Burma', region: 'Asia Tenggara', lon: 100.56, lat: 14.35, description: "Pasukan Konbaung merebut dan membakar Ayutthaya setelah pengepungan panjang. Taksin kemudian mengusir Burma dan memindahkan ibu kota ke Thonburi, lalu Rama I ke Bangkok.", civilizationId: 'ayutthaya-siam', kind: 'perang' },
  { id: 'e-cook', year: 1770, title: 'James Cook di Botany Bay', region: 'Oseania', lon: 151.23, lat: -34.0, description: "Kapten James Cook mendarat di Botany Bay dan mengklaim pantai timur Australia untuk Inggris tanpa persetujuan penduduk Aborigin yang telah tinggal di sana ribuan tahun.", civilizationId: 'aborigin-australia', kind: 'politik' },
  { id: 'e-armada-pertama', year: 1788, title: 'Armada Pertama tiba di Sydney', region: 'Oseania', lon: 151.21, lat: -33.86, description: "Sebelas kapal Inggris membawa sekitar seribu lebih narapidana, prajurit, dan pejabat untuk mendirikan koloni hukuman di Sydney Cove. Bagi bangsa Eora dan komunitas Aborigin lain, kedatangan ini awal kehilangan tanah, wabah, dan kekerasan.", civilizationId: 'aborigin-australia', kind: 'politik' },
  { id: 'e-jenner', year: 1796, title: 'Edward Jenner menguji vaksin cacar', region: 'Eropa', lon: -2.46, lat: 51.69, description: "Dokter desa Edward Jenner menyuntikkan nanah cacar sapi kepada seorang anak dan membuktikan bahwa ia kebal terhadap cacar. Vaksinasi yang diturunkan darinya akhirnya melenyapkan cacar dari dunia pada 1980.", civilizationId: 'inggris-raya', kind: 'teknologi' },
  { id: 'e-padri', year: 1803, title: 'Perang Padri dimulai', region: 'Nusantara', lon: 100.13, lat: 0.02, description: "Pertikaian kaum Padri, yang ingin memurnikan praktik Islam, dengan kaum adat di Minangkabau berubah menjadi perang melawan Belanda yang membantu kaum adat. Perang berakhir setelah Bonjol jatuh pada 1837 dan perlawanan terakhir dipadamkan pada 1838.", civilizationId: 'dharmasraya-pagaruyung', kind: 'perang' },
  { id: 'e-haiti', year: 1804, title: 'Haiti merdeka', region: 'Amerika', lon: -72.69, lat: 19.45, description: "Setelah bertahun-tahun pemberontakan para budak yang dipimpin Toussaint Louverture dan kemudian Jean-Jacques Dessalines, Haiti menyatakan kemerdekaan dari Prancis. Haiti menjadi republik pertama yang dipimpin bekas budak.", kind: 'politik' },
  { id: 'e-stockton', year: 1825, title: 'Kereta api penumpang pertama', region: 'Eropa', lon: -1.55, lat: 54.5, description: "Lokomotif uap buatan George Stephenson menarik gerbong di jalur Stockton–Darlington, Inggris. Dalam beberapa dekade, rel merambah daratan Eropa, Amerika, dan India, mengubah cara orang bepergian dan berdagang.", civilizationId: 'inggris-raya', kind: 'teknologi' },
  { id: 'e-london-1824', year: 1824, title: 'Traktat London Inggris–Belanda', region: 'Nusantara', lon: -0.12, lat: 51.5, description: "Inggris dan Belanda membagi pengaruh di dunia Melayu: Semenanjung Malaya dan Singapura untuk Inggris, Sumatra dan wilayah di selatan Selat Malaka untuk Belanda. Penduduk setempat tidak diajak berunding, tetapi batas ini membentuk peta Asia Tenggara modern.", civilizationId: 'hindia-belanda', kind: 'politik' },
  { id: 'e-jagaraga', year: 1849, title: 'Pertempuran Jagaraga', region: 'Nusantara', lon: 115.17, lat: -8.1, description: "Pasukan Buleleng di bawah Patih I Gusti Ketut Jelantik membangun benteng di Jagaraga dan menahan dua ekspedisi Belanda sebelum akhirnya jatuh pada ekspedisi ketiga di April 1849. Perang ini menjadi bagian dari rangkaian penaklukan Bali oleh Belanda.", civilizationId: 'bali', kind: 'perang' },
  { id: 'e-banjar-1859', year: 1859, title: 'Perang Banjar', region: 'Nusantara', lon: 114.8, lat: -3.4, description: "Pangeran Antasari memimpin perlawanan rakyat Banjar melawan Belanda setelah pergantian takhta yang diatur oleh pemerintah kolonial. Perang berlangsung bertahun-tahun di hulu Barito hingga masa 1860-an dan melibatkan banyak ulama dan petani.", civilizationId: 'banjar', kind: 'perang' },
  { id: 'e-max-havelaar', year: 1860, title: 'Max Havelaar terbit', region: 'Eropa', lon: 4.9, lat: 52.37, description: "Eduard Douwes Dekker, dengan nama pena Multatuli, menerbitkan novel yang membuka kepada pembaca Belanda tentang penderitaan petani Jawa di bawah Tanam Paksa. Buku ini mendorong kritik dan kemudian pembaruan kebijakan kolonial.", civilizationId: 'hindia-belanda', kind: 'budaya' },
  { id: 'e-suez', year: 1869, title: 'Terusan Suez dibuka', region: 'Afrika', lon: 32.31, lat: 31.26, description: "Terusan sepanjang sekitar 160 km yang digali ribuan pekerja Mesir menghubungkan Laut Tengah dan Laut Merah. Perjalanan dari Eropa ke Asia lebih pendek, sehingga perdagangan ke Nusantara berubah dan banyak pekerja tewas dalam penggaliannya.", kind: 'teknologi' },
  { id: 'e-aceh-1873', year: 1873, title: 'Perang Aceh dimulai', region: 'Nusantara', lon: 95.32, lat: 5.55, description: "Belanda menyatakan perang pada Kesultanan Aceh pada Maret 1873. Ekspedisi pertama gagal dan komandannya tewas; perlawanan yang dipimpin ulama, hulubalang, dan tokoh seperti Cut Nyak Dhien berlangsung hingga sekitar 1904 dan sesudahnya dalam bentuk gerilya.", civilizationId: 'kesultanan-awal', kind: 'perang' },
  { id: 'e-krakatau', year: 1883, title: 'Letusan Krakatau', region: 'Nusantara', lon: 105.42, lat: -6.1, description: "Pada 26–27 Agustus, Gunung Krakatau meletus dan menimbulkan tsunami yang menewaskan sekitar 36.000 orang di pesisir Jawa dan Sumatra. Suara letusannya terdengar ribuan kilometer, dan debu mengubah warna langit di seluruh dunia selama berbulan-bulan.", civilizationId: 'hindia-belanda', kind: 'bencana' },
  { id: 'e-politik-etis', year: 1901, title: 'Politik Etis diumumkan', region: 'Nusantara', lon: 4.3, lat: 52.08, description: "Ratu Wilhelmina menyebut tugas moral Belanda terhadap rakyat Hindia dalam pidato takhta. Program pendidikan, irigasi, dan emigrasi berjalan, meski jangkauannya terbatas dan banyak yang tetap tak bersekolah. Dari sekolah-sekolah itu lahir kaum terpelajar pergerakan nasional.", civilizationId: 'hindia-belanda', kind: 'politik' },
  { id: 'e-wright', year: 1903, title: 'Penerbangan pertama Wright bersaudara', region: 'Amerika', lon: -75.7, lat: 36.0, description: "Orville dan Wilbur Wright menerbangkan pesawat bermotor yang dikendalikan di Kitty Hawk, Carolina Utara, selama 12 detik. Dua dekade kemudian penerbangan sudah mengubah perang dan perjalanan jarak jauh.", civilizationId: 'amerika-serikat', kind: 'teknologi' },
  { id: 'e-badung', year: 1906, title: 'Puputan Badung', region: 'Nusantara', lon: 115.22, lat: -8.65, description: "Ketika pasukan Belanda mendekati Denpasar, raja, keluarga bangsawan, dan pengikutnya berjalan keluar dengan pakaian upacara dan melawan sampai gugur. Ratusan orang tewas. Tindakan perang habis-habisan ini disebut puputan.", civilizationId: 'bali', kind: 'perang' },
  { id: 'e-klungkung', year: 1908, title: 'Puputan Klungkung', region: 'Nusantara', lon: 115.4, lat: -8.53, description: "Dewa Agung dari Klungkung, raja yang dihormati sebagai yang tertinggi di antara raja-raja Bali, memimpin puputan terakhir melawan Belanda. Setelahnya seluruh Bali berada di bawah pemerintahan kolonial.", civilizationId: 'bali', kind: 'perang' },
  // ===== Modern =====
  { id: 'e-xinhai', year: 1911, title: 'Revolusi Xinhai', region: 'Asia Timur', lon: 114.3, lat: 30.55, description: "Pemberontakan tentara di Wuchang pada Oktober 1911 menjalar ke banyak provinsi. Kaisar cilik Puyi turun takhta pada Februari 1912, mengakhiri lebih dari dua ribu tahun pemerintahan kekaisaran, dan Sun Yat-sen menjadi presiden sementara Republik Tiongkok.", civilizationId: 'tiongkok-modern', kind: 'politik' },
  { id: 'e-sarekat-islam', year: 1912, title: 'Sarekat Islam berdiri', region: 'Nusantara', lon: 110.82, lat: -7.57, description: "Sarekat Dagang Islam dari Surakarta berubah menjadi Sarekat Islam di bawah H.O.S. Tjokroaminoto dan menjadi organisasi massa pertama di Hindia. Anggotanya mencapai ratusan ribu orang di desa dan kota.", civilizationId: 'hindia-belanda', kind: 'politik' },
  { id: 'e-muhammadiyah', year: 1912, title: 'Muhammadiyah didirikan', region: 'Nusantara', lon: 110.37, lat: -7.8, description: "Ahmad Dahlan mendirikan Muhammadiyah di Yogyakarta untuk memurnikan praktik Islam dan memajukan pendidikan serta layanan sosial. Sekolah dan rumah sakitnya kemudian menyebar ke seluruh nusantara.", civilizationId: 'hindia-belanda', kind: 'agama' },
  { id: 'e-volksraad', year: 1918, title: 'Volksraad dibuka', region: 'Nusantara', lon: 106.83, lat: -6.17, description: "Dewan perwakilan semu dibuka di Batavia dengan anggota pribumi, Tionghoa, dan Belanda. Wewenangnya terbatas pada memberi saran, tetapi tokoh pribumi memakainya untuk menyuarakan tuntutan mereka.", civilizationId: 'hindia-belanda', kind: 'politik' },
  { id: 'e-flu-spanyol', year: 1918, title: 'Flu Spanyol', region: 'Eropa', lon: -3.7, lat: 40.42, description: "Pandemi influenza menyebar bersama pasukan dan kapal di akhir Perang Dunia I, dan menewaskan puluhan juta orang di seluruh dunia. Namanya berasal dari pers Spanyol yang bebas menulisnya; asal penyakit ini tidak pasti.", kind: 'bencana' },
  { id: 'e-turki-republik', year: 1923, title: 'Republik Turki diproklamasikan', region: 'Asia Barat', lon: 32.85, lat: 39.93, description: "Setelah Perang Kemerdekaan Turki, Mustafa Kemal memproklamasikan republik dengan Ankara sebagai ibu kota. Kesultanan dihapus pada 1922 dan kekhalifahan pada 1924, sehingga mengakhiri masa Utsmaniyah.", civilizationId: 'ottoman', kind: 'politik' },
  { id: 'e-nu', year: 1926, title: 'Nahdlatul Ulama berdiri', region: 'Nusantara', lon: 112.75, lat: -7.25, description: "Hasyim Asy'ari dan para kiai pesantren mendirikan Nahdlatul Ulama di Surabaya untuk menjaga tradisi mazhab dan menyuarakan kepentingan umat pedesaan. NU kemudian menjadi salah satu organisasi Islam terbesar di dunia.", civilizationId: 'hindia-belanda', kind: 'agama' },
  { id: 'e-penisilin', year: 1928, title: 'Penisilin ditemukan', region: 'Eropa', lon: -0.17, lat: 51.52, description: "Alexander Fleming menemukan bahwa jamur Penicillium mematikan bakteri di cawan kulturnya. Penemuan itu baru dimanfaatkan sebagai obat oleh Howard Florey dan Ernst Chain pada awal 1940-an, dan sejak itu menyelamatkan jutaan nyawa.", civilizationId: 'inggris-raya', kind: 'teknologi' },
  { id: 'e-depresi', year: 1929, title: 'Depresi Besar', region: 'Amerika', lon: -74.01, lat: 40.71, description: "Bursa saham New York anjlok pada Oktober 1929 dan memicu krisis ekonomi global. Jutaan orang kehilangan pekerjaan, harga komoditas ekspor jatuh, dan petani di koloni seperti Hindia Belanda ikut menanggung akibatnya.", civilizationId: 'amerika-serikat', kind: 'bencana' },
  { id: 'e-pearl-harbor', year: 1941, title: 'Serangan Pearl Harbor', region: 'Oseania', lon: -157.97, lat: 21.36, description: "Pesawat Jepang menyerang pangkalan laut Amerika di Hawaii pada 7 Desember. Amerika Serikat memasuki Perang Dunia II, dan dalam beberapa bulan Jepang bergerak ke Filipina, Malaya, dan Hindia Belanda.", civilizationId: 'jepang-modern', kind: 'perang' },
  { id: 'e-wannsee', year: 1942, title: 'Konferensi Wannsee', region: 'Eropa', lon: 13.17, lat: 52.43, description: "Pejabat Nazi bertemu di sebuah vila di pinggir Berlin untuk mengoordinasikan pembunuhan massal orang Yahudi Eropa. Holocaust menewaskan sekitar enam juta orang Yahudi, bersama jutaan korban lain seperti Roma dan tawanan perang.", kind: 'perang' },
  { id: 'e-laut-jawa', year: 1942, title: 'Pertempuran Laut Jawa', region: 'Nusantara', lon: 112.0, lat: -6.0, description: "Armada gabungan Sekutu (ABDA) dikalahkan armada Jepang pada 27 Februari. Dua pekan kemudian Hindia Belanda menyerah, dan tentara Jepang menguasai kepulauan ini.", civilizationId: 'jepang-modern', kind: 'perang' },
  { id: 'e-pbb', year: 1945, title: 'PBB didirikan', region: 'Amerika', lon: -122.42, lat: 37.78, description: "Wakil dari lima puluh negara menandatangani Piagam PBB di San Francisco untuk mencegah perang besar berikutnya. Piagam mulai berlaku pada 24 Oktober 1945, dan Indonesia bergabung pada 1950.", kind: 'politik' },
  { id: 'e-surabaya-1945', year: 1945, title: 'Pertempuran Surabaya', region: 'Nusantara', lon: 112.75, lat: -7.25, description: "Setelah ultimatum pasukan Inggris-India, arek-arek Surabaya, laskar, dan tentara melawan hingga berminggu-minggu pada November 1945, dan ribuan orang tewas. Tanggal 10 November kini diperingati sebagai Hari Pahlawan.", civilizationId: 'republik-indonesia', kind: 'perang' },
  { id: 'e-bandung-lautan-api', year: 1946, title: 'Bandung Lautan Api', region: 'Nusantara', lon: 107.61, lat: -6.91, description: "Menghadapi ultimatum Sekutu agar mengosongkan Bandung selatan, ratusan ribu penduduk mengungsi dan pejuang membakar bangunan sebelum meninggalkan kota pada 23–24 Maret 1946.", civilizationId: 'republik-indonesia', kind: 'perang' },
  { id: 'e-linggarjati', year: 1946, title: 'Perundingan Linggarjati', region: 'Nusantara', lon: 108.5, lat: -6.95, description: "Republik Indonesia dan Belanda menyepakati bahwa Belanda mengakui kekuasaan de facto Republik atas Jawa, Madura, dan Sumatra. Perbedaan penafsiran naskah ini mengantar ke Agresi Militer I pada 1947.", civilizationId: 'republik-indonesia', kind: 'politik' },
  { id: 'e-agresi-1', year: 1947, title: 'Agresi Militer Belanda I', region: 'Nusantara', lon: 110.37, lat: -7.8, description: "Belanda melancarkan 'aksi polisionil' pada 21 Juli 1947 dan merebut wilayah perkebunan di Jawa dan Sumatra. Dewan Keamanan PBB mendesak gencatan senjata, dan perundingan berlanjut di kapal Renville.", civilizationId: 'republik-indonesia', kind: 'perang' },
  { id: 'e-agresi-2', year: 1948, title: 'Agresi Militer Belanda II', region: 'Nusantara', lon: 110.37, lat: -7.8, description: "Pada 19 Desember 1948 Belanda menyerbu Yogyakarta, menawan Soekarno, Hatta, dan para pemimpin lainnya. Sjafruddin Prawiranegara membentuk Pemerintah Darurat Republik Indonesia di Sumatra sehingga pemerintahan tidak kosong.", civilizationId: 'republik-indonesia', kind: 'perang' },
  { id: 'e-apartheid', year: 1948, title: 'Apartheid diresmikan di Afrika Selatan', region: 'Afrika', lon: 28.19, lat: -25.75, description: "Pemerintah Partai Nasional menetapkan undang-undang yang memisahkan penduduk berdasarkan ras dalam tempat tinggal, pekerjaan, dan pendidikan. Perlawanan panjang berakhir dengan pemilu multiras pada 1994.", kind: 'politik' },
  { id: 'e-serangan-umum', year: 1949, title: 'Serangan Umum 1 Maret', region: 'Nusantara', lon: 110.37, lat: -7.8, description: "Pasukan Republik menyerbu Yogyakarta yang diduduki Belanda dan menguasainya selama enam jam. Serangan ini menunjukkan kepada dunia bahwa Republik masih ada, dan Sultan Hamengkubuwono IX berperan dalam persiapannya.", civilizationId: 'republik-indonesia', kind: 'perang' },
  { id: 'e-perang-korea', year: 1950, title: 'Perang Korea', region: 'Asia Timur', lon: 127.0, lat: 38.0, description: "Korea Utara menyeberangi paralel ke-38 dan menyerang Selatan. Perang tiga tahun, dengan PBB dan Tiongkok ikut terlibat, berakhir dengan gencatan senjata tanpa perjanjian damai dan dengan jutaan korban.", civilizationId: 'korea', kind: 'perang' },
  { id: 'e-dien-bien-phu', year: 1954, title: 'Pertempuran Dien Bien Phu', region: 'Asia Tenggara', lon: 102.98, lat: 21.38, description: "Pasukan Viet Minh di bawah Vo Nguyen Giap mengepung dan mengalahkan garnisun Prancis di lembah terpencil. Kekalahan ini mengakhiri kekuasaan Prancis di Indochina dan mengantar ke Perjanjian Jenewa.", kind: 'perang' },
  { id: 'e-suez-1956', year: 1956, title: 'Krisis Suez', region: 'Afrika', lon: 32.55, lat: 29.97, description: "Nasser menasionalisasi Terusan Suez, dan Inggris, Prancis, serta Israel menyerang Mesir. Tekanan Amerika Serikat dan Uni Soviet memaksa mereka mundur, menandai menurunnya pengaruh Inggris dan Prancis.", civilizationId: 'inggris-raya', kind: 'perang' },
  { id: 'e-gnb', year: 1961, title: 'Gerakan Non-Blok didirikan', region: 'Eropa', lon: 20.46, lat: 44.82, description: "Tito, Nehru, Nasser, Nkrumah, dan Soekarno menggelar konferensi di Beograd untuk menjaga negara baru merdeka tetap netral dari blok Barat dan Timur.", kind: 'politik' },
  { id: 'e-rudal-kuba', year: 1962, title: 'Krisis Rudal Kuba', region: 'Amerika', lon: -82.37, lat: 23.13, description: "Amerika Serikat dan Uni Soviet nyaris berperang nuklir selama dua belas hari ketika rudal Soviet ditemukan di Kuba. Krisis berakhir lewat kesepakatan rahasia, dan kedua negara kemudian membuka saluran telepon langsung.", kind: 'politik' },
  { id: 'e-1965', year: 1965, title: 'Peristiwa 1965', region: 'Nusantara', lon: 106.84, lat: -6.2, description: "Pada 30 September–1 Oktober 1965 sejumlah perwira tinggi Angkatan Darat diculik dan dibunuh. Sesudahnya terjadi kekerasan massal terhadap anggota dan orang yang dituduh terkait Partai Komunis Indonesia, dengan perkiraan korban dari ratusan ribu hingga lebih dari satu juta. Para sejarawan masih memperdebatkan peran berbagai pihak.", civilizationId: 'republik-indonesia', kind: 'politik' },
  { id: 'e-asean', year: 1967, title: 'ASEAN didirikan', region: 'Asia Tenggara', lon: 100.5, lat: 13.75, description: "Indonesia, Malaysia, Filipina, Singapura, dan Thailand menandatangani Deklarasi Bangkok untuk kerja sama ekonomi dan perdamaian kawasan. Brunei, Vietnam, Laos, Myanmar, dan Kamboja bergabung kemudian.", kind: 'politik' },
  { id: 'e-palapa', year: 1976, title: 'Satelit Palapa A1 diluncurkan', region: 'Amerika', lon: -80.58, lat: 28.39, description: "Indonesia menjadi salah satu negara pertama yang memiliki satelit komunikasi domestik. Dari satelit ini siaran televisi dan telepon menjangkau kepulauan dari Sabang sampai Merauke.", civilizationId: 'republik-indonesia', kind: 'teknologi' },
  { id: 'e-chernobyl', year: 1986, title: 'Bencana Chernobyl', region: 'Eropa', lon: 30.1, lat: 51.39, description: "Reaktor nomor 4 pembangkit nuklir Chernobyl meledak setelah uji coba yang gagal. Puluhan ribu orang diungsikan dan awan radioaktif menyebar ke Eropa. Jumlah korban jangka panjang masih diperdebatkan.", civilizationId: 'rusia-soviet', kind: 'bencana' },
  { id: 'e-apartheid-akhir', year: 1994, title: 'Pemilu multiras pertama di Afrika Selatan', region: 'Afrika', lon: 28.19, lat: -25.75, description: "Warga kulit hitam mengantre berjam-jam untuk memberikan suara untuk pertama kalinya. Nelson Mandela menjadi presiden dan membentuk Komisi Kebenaran dan Rekonsiliasi.", kind: 'politik' },
  { id: 'e-krismon', year: 1997, title: 'Krisis moneter Asia', region: 'Asia Tenggara', lon: 100.5, lat: 13.75, description: "Thailand melepas patokan baht pada Juli 1997, dan krisis merambat ke Indonesia, Korea Selatan, dan Malaysia. Rupiah anjlok, harga melonjak, dan krisis ini ikut mendorong tumbangnya Orde Baru pada 1998.", civilizationId: 'republik-indonesia', kind: 'bencana' },
  { id: 'e-timor-leste', year: 2002, title: 'Timor Leste merdeka', region: 'Nusantara', lon: 125.57, lat: -8.56, description: "Setelah referendum 1999 dan masa administrasi PBB, Timor Leste menjadi negara berdaulat pada 20 Mei 2002. Perjalanan ke kemerdekaan diwarnai kekerasan panjang sejak 1975.", kind: 'politik' },
  { id: 'e-bom-bali', year: 2002, title: 'Bom Bali', region: 'Nusantara', lon: 115.17, lat: -8.72, description: "Ledakan bom di Kuta pada 12 Oktober 2002 menewaskan 202 orang dari puluhan negara, termasuk banyak warga Indonesia. Peristiwa ini mendorong Indonesia memperkuat penanganan terorisme.", civilizationId: 'republik-indonesia', kind: 'bencana' },
  { id: 'e-gempa-yogya', year: 2006, title: 'Gempa Yogyakarta', region: 'Nusantara', lon: 110.33, lat: -7.96, description: "Gempa 27 Mei 2006 menghancurkan Bantul dan sekitarnya, menewaskan lebih dari lima ribu orang dan merusak ratusan ribu rumah. Warga membangun kembali dengan gotong royong dan bantuan dari banyak daerah.", civilizationId: 'republik-indonesia', kind: 'bencana' },
  { id: 'e-paris-iklim', year: 2015, title: 'Perjanjian Paris tentang iklim', region: 'Eropa', lon: 2.35, lat: 48.86, description: "Hampir semua negara sepakat untuk menahan kenaikan suhu global jauh di bawah 2 derajat Celsius dibanding masa praindustri. Setiap negara menentukan target pengurangan emisinya sendiri.", kind: 'politik' },
  { id: 'e-asian-games', year: 2018, title: 'Asian Games Jakarta–Palembang', region: 'Nusantara', lon: 106.8, lat: -6.22, description: "Indonesia menjadi tuan rumah Asian Games ke-18 di dua kota, Jakarta dan Palembang, dengan sekitar 11.000 atlet dari 45 negara. Ajang ini juga memperlihatkan pembangunan sarana transportasi kota.", civilizationId: 'republik-indonesia', kind: 'budaya' },
  // ===== Tambahan lintas era =====
  { id: 'e-dan-no-ura', year: 1185, title: 'Pertempuran Dan-no-ura', region: 'Asia Timur', lon: 130.93, lat: 33.96, description: "Klan Minamoto mengalahkan klan Taira dalam pertempuran laut di Selat Shimonoseki, mengakhiri Perang Genpei. Kisahnya dituturkan dalam Heike Monogatari, dan Kaisar kecil Antoku tenggelam bersama neneknya.", civilizationId: 'jepang-klasik', kind: 'perang' },
  { id: 'e-kamakura', year: 1192, title: 'Yoritomo menjadi shogun', region: 'Asia Timur', lon: 139.55, lat: 35.32, description: "Minamoto no Yoritomo menerima gelar shogun dari kaisar dan memerintah dari Kamakura. Sejak itu para samurai memegang kekuasaan nyata di Jepang, sedangkan kaisar tetap berada di Kyoto.", civilizationId: 'jepang-klasik', kind: 'politik' },
  { id: 'e-magellan', year: 1521, title: 'Magellan tewas di Mactan', region: 'Asia Tenggara', lon: 124.0, lat: 10.3, description: "Ferdinand Magellan tewas dalam bentrokan dengan pasukan Lapulapu di Filipina. Kapal Victoria di bawah Juan Sebastián Elcano melanjutkan perjalanan dan kembali ke Spanyol pada 1522, pelayaran keliling dunia pertama.", civilizationId: 'kolonialisme-eropa', kind: 'perdagangan' },
  { id: 'e-panipat-1526', year: 1526, title: 'Pertempuran Panipat Pertama', region: 'Asia Selatan', lon: 76.97, lat: 29.39, description: "Babur dengan meriam dan senapan mengalahkan Ibrahim Lodi dari Delhi. Kemenangan ini membuka jalan bagi berdirinya Kekaisaran Mughal di India utara.", civilizationId: 'mughal-india', kind: 'perang' },
  { id: 'e-taj-mahal', year: 1632, title: 'Taj Mahal mulai dibangun', region: 'Asia Selatan', lon: 78.04, lat: 27.17, description: "Syah Jahan memerintahkan pembangunan makam marmer bagi istrinya Mumtaz Mahal di Agra. Ribuan pengrajin dari berbagai wilayah bekerja bertahun-tahun, dan kompleksnya rampung sekitar 1653.", civilizationId: 'mughal-india', kind: 'budaya' },
  { id: 'e-sakoku', year: 1639, title: 'Jepang menutup diri (sakoku)', region: 'Asia Timur', lon: 129.87, lat: 32.75, description: "Shogun Tokugawa membatasi hubungan dagang asing hanya pada Belanda dan Tiongkok melalui Nagasaki, serta melarang orang Jepang bepergian ke luar negeri. Kebijakan ini bertahan hingga kedatangan kapal hitam Perry pada 1853.", civilizationId: 'jepang-klasik', kind: 'politik' },
  { id: 'e-taiping', year: 1850, title: 'Pemberontakan Taiping', region: 'Asia Timur', lon: 110.1, lat: 23.7, description: "Hong Xiuquan, yang mengaku saudara Yesus, memimpin pemberontakan petani di Guangxi melawan Qing. Perang saudara sampai 1864 menewaskan sekitar dua puluh juta orang menurut perkiraan umum, termasuk salah satu konflik paling mematikan abad ke-19.", civilizationId: 'ming-qing', kind: 'perang' },
  { id: 'e-sepoy', year: 1857, title: 'Pemberontakan Sepoy', region: 'Asia Selatan', lon: 77.7, lat: 28.98, description: "Tentara sepoy India memberontak melawan Kompeni Inggris di Meerut, lalu bergabung dengan penguasa dan petani di India utara. Setelah pemberontakan dipadamkan, Inggris membubarkan Kompeni dan memerintah India langsung sebagai mahkota.", civilizationId: 'inggris-raya', kind: 'perang' },
  { id: 'e-trinil', year: 1891, title: 'Fosil Manusia Jawa ditemukan', region: 'Nusantara', lon: 111.36, lat: -7.37, description: "Eugène Dubois menemukan tempurung kepala dan tulang paha di tepi Bengawan Solo di Trinil. Temuan ini kemudian dikenal sebagai Homo erectus dan memperlihatkan bahwa Jawa dihuni manusia purba sejak lama.", civilizationId: 'hindia-belanda', kind: 'budaya' },
  { id: 'e-pemilu-1955', year: 1955, title: 'Pemilu pertama Indonesia', region: 'Nusantara', lon: 106.84, lat: -6.2, description: "Rakyat memilih anggota DPR pada 29 September dan Konstituante pada Desember 1955. Pemilu ini diikuti puluhan partai dan sering dikenang sebagai salah satu pemilu paling bebas dalam sejarah Indonesia.", civilizationId: 'republik-indonesia', kind: 'politik' },
];
